import java.util.Scanner;
public class RemoveCharacterFromString { public static void main(String[] args){Scanner sc=new Scanner(System.in);String s=sc.nextLine();char ch=sc.nextLine().charAt(0);StringBuilder out=new StringBuilder();for(int i=0;i<s.length();i++)if(s.charAt(i)!=ch)out.append(s.charAt(i));System.out.println(out);} }